<?php
namespace App\Console\Commands;use App\Jobs\SyncProductToGoogleMerchant;use App\Models\Product;use Illuminate\Console\Command;class SyncGoogleMerchantProducts extends Command{protected $signature='merchant:sync {--stale : Only products not successfully synced}';protected $description='Queue eligible Prinx products for Google Merchant synchronization';public function handle():int{$q=Product::merchantEligible();if($this->option('stale'))$q->where(fn($x)=>$x->whereNull('merchant_last_synced_at')->orWhere('merchant_sync_status','!=','synced'));$count=0;$q->select('id')->chunkById(100,function($ps)use(&$count){foreach($ps as$p){SyncProductToGoogleMerchant::dispatch($p->id);$count++;}});$this->info("Queued {$count} products.");return self::SUCCESS;}}
